//! Independent `aer-route-v1` target-3 route-write golden contract (#79).
//!
//! Expected bytes are committed in `tests/golden/uart/route_write_target3.json`,
//! hand-computed from the silicon-hdl routing contract, not generated by the
//! codec under test. No serial port or FPGA is opened by these tests.

use serde::Deserialize;
use silicon_bridge::{
    AER_ROUTE_ENTRY_COUNT, AerRouteEntry, AerRouteError, AerRouteTable, ROUTE_TABLE_TARGET,
    ROUTE_WRITE_COMMAND, ROUTE_WRITE_LEN, SILICON_BRIDGE_V3_RX_LEN, SILICON_BRIDGE_V3_TX_LEN,
    encode_route_table, encode_route_write_word,
};
use std::{fs, path::PathBuf};

#[derive(Debug, Deserialize)]
struct RouteFixture {
    command: String,
    target: u8,
    frame_bytes: usize,
    identity_frames: Vec<String>,
    multi_hop_example: MultiHop,
}

#[derive(Debug, Deserialize)]
struct MultiHop {
    frames: Vec<String>,
}

fn parse_hex(hex: &str) -> Vec<u8> {
    assert!(hex.len().is_multiple_of(2));
    (0..hex.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&hex[index..index + 2], 16).expect("hex byte"))
        .collect()
}

fn fixture() -> RouteFixture {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/golden/uart/route_write_target3.json");
    serde_json::from_str(&fs::read_to_string(path).expect("route fixture")).expect("route JSON")
}

#[test]
fn identity_table_frames_match_independent_bytes() {
    let fix = fixture();
    assert_eq!(fix.command, "0xA5");
    assert_eq!(fix.command, format!("0x{ROUTE_WRITE_COMMAND:02X}"));
    assert_eq!(fix.target, ROUTE_TABLE_TARGET);
    assert_eq!(fix.frame_bytes, ROUTE_WRITE_LEN);
    assert_eq!(fix.identity_frames.len(), AER_ROUTE_ENTRY_COUNT);

    let frames = encode_route_table(&AerRouteTable::identity()).unwrap();
    for (address, expected_hex) in fix.identity_frames.iter().enumerate() {
        let expected = parse_hex(expected_hex);
        assert_eq!(expected.len(), ROUTE_WRITE_LEN);
        assert_eq!(expected[0], ROUTE_WRITE_COMMAND);
        assert_eq!(expected[1], ROUTE_TABLE_TARGET);
        assert_eq!(expected[2], address as u8);
        assert_eq!(frames[address].as_slice(), expected.as_slice());
        assert_eq!(
            encode_route_write_word(address as u8, 0xC000 | address as u16)
                .unwrap()
                .as_slice(),
            expected.as_slice()
        );
    }
}

#[test]
fn multi_hop_example_frames_match_independent_bytes() {
    let fix = fixture();
    // 0 -> 1 -> 2: entry 0 forwards, entry 1 forwards, entry 2 terminal.
    let mut table = AerRouteTable::identity();
    table = table
        .with_entry(0, AerRouteEntry::forwarding(1).unwrap())
        .unwrap()
        .with_entry(1, AerRouteEntry::forwarding(2).unwrap())
        .unwrap()
        .with_entry(2, AerRouteEntry::terminal(2).unwrap())
        .unwrap();
    table.validate().expect("0 -> 1 -> 2 fits the hop budget");

    let frames = encode_route_table(&table).unwrap();
    assert_eq!(fix.multi_hop_example.frames.len(), 3);
    for (address, expected_hex) in fix.multi_hop_example.frames.iter().enumerate() {
        assert_eq!(
            frames[address].as_slice(),
            parse_hex(expected_hex).as_slice()
        );
    }
    // Entries not in the chain keep their identity words.
    for (address, frame) in frames.iter().enumerate().skip(3) {
        assert_eq!(frame[3..5], [0xC0, address as u8]);
    }
}

#[test]
fn route_write_rejects_contract_violations() {
    assert_eq!(
        encode_route_write_word(16, 0xC000),
        Err(AerRouteError::AddressOutOfRange { address: 16 })
    );
    assert_eq!(
        encode_route_write_word(255, 0xC000),
        Err(AerRouteError::AddressOutOfRange { address: 255 })
    );
    for word in [0xC010, 0x8010, 0xFFF0] {
        assert!(matches!(
            encode_route_write_word(0, word),
            Err(AerRouteError::ReservedBits { word: w, .. }) if w == word
        ));
    }
    assert_eq!(
        AerRouteTable::from_words(&[0xC000; 15]),
        Err(AerRouteError::WrongEntryCount { actual: 15 })
    );
    // Cycle: 0 -> 1 -> 0 never terminates.
    let cyclic = AerRouteTable::from_words(&{
        let mut w = [0xC000u16; 16];
        w[0] = 0x8001;
        w[1] = 0x8000;
        w
    })
    .unwrap();
    assert!(matches!(
        cyclic.validate(),
        Err(AerRouteError::OverBudget { .. })
    ));
}

#[test]
fn v3_stimulus_framing_is_unchanged() {
    // Route writes are a separate 0xA5 command; the 33-byte request and
    // 36-byte response contract must not move.
    assert_eq!(SILICON_BRIDGE_V3_TX_LEN, 33);
    assert_eq!(SILICON_BRIDGE_V3_RX_LEN, 36);
}
